    #[test]
    fn wrapped_bidi_keeps_external_space_outside_single_fragments_per_line() {
        let plain = |content: &str| {
            let mut style = w3cos_std::style::Style::default();
            style.display = Display::Inline;
            style.font_family = Some("Ahem".to_string());
            style.line_height = 1.0;
            w3cos_std::Component::text(content, style)
        };
        let decorated = |content: &str| {
            let mut style = plain("").style;
            style.border_width = 3.0;
            style.line_height = 3.0;
            style.padding.left = w3cos_std::style::Spacing::Px(16.0);
            style.padding.right = w3cos_std::style::Spacing::Px(16.0);
            w3cos_std::Component::row(style, vec![plain(content)])
        };
        let mut style = plain("").style;
        style.display = Display::Block;
        style.width = w3cos_std::style::Dimension::Em(28.0);
        style.box_sizing = w3cos_std::style::BoxSizing::ContentBox;
        style.flex_wrap = w3cos_std::style::FlexWrap::Wrap;
        let mut line = w3cos_std::Component::row(
            style,
            vec![
                decorated("pppp pppX ppXp \u{202e} ppXp XXpp XppX "),
                plain("pppX XXXp pXXp "),
                decorated("XpXp ppXX XXpX pXpX \u{202c} XXpX XXXp "),
            ],
        );
        reorder_explicit_bidi_inline_rows(&mut line);
        let runs = line
            .children
            .iter()
            .map(|child| {
                let content = match &child.kind {
                    ComponentKind::Text { content } => content.clone(),
                    _ => child
                        .children
                        .iter()
                        .filter_map(|inner| {
                            if let ComponentKind::Text { content } = &inner.kind {
                                Some(content.as_str())
                            } else {
                                None
                            }
                        })
                        .collect::<String>(),
                };
                (child.style.border_width, content)
            })
            .collect::<Vec<_>>();
        let fragment = line
            .children
            .iter()
            .find_map(|child| {
                if child.style.border_width > 0.0
                    && let ComponentKind::Text { content } = &child.kind
                    && content.trim_matches(is_css_whitespace) == "pXpX"
                {
                    Some(content.as_str())
                } else {
                    None
                }
            })
            .unwrap_or_else(|| panic!("missing decorated pXpX fragment: {runs:?}"));
        assert_eq!(fragment, "pXpX");
    }

    #[test]
    fn inline_override_survives_anonymous_block_lowering() {
        crate::stylesheet::clear_rules();
        crate::stylesheet::register_rule(
            "div",
            &[
                ("display", "inline"),
                ("direction", "rtl"),
                ("unicode-bidi", "bidi-override"),
            ],
        );
        let mut document = Document::new();
        document.set_html_document(false);
        let paragraph = document.create_element("p");
        paragraph.set_text_content(&mut document, "instruction");
        document.body().append_child(&mut document, paragraph);
        let before = document.create_text_node("\n        ");
        document.body().append_child(&mut document, before);
        let inline = document.create_element("div");
        inline.set_attribute(&mut document, "class", "override");
        let content = document.create_text_node("SSAP SSAP");
        inline.append_child(&mut document, content);
        document.body().append_child(&mut document, inline);
        let after = document.create_text_node("\n    ");
        document.body().append_child(&mut document, after);
        let tree = document.to_component_tree();
        fn text(component: &w3cos_std::Component) -> String {
            match &component.kind {
                w3cos_std::ComponentKind::Text { content } => content.clone(),
                _ => component.children.iter().map(text).collect(),
            }
        }
        assert_eq!(text(&tree).trim(), "instructionPASS PASS");
        crate::stylesheet::clear_rules();
    }

    #[test]
    fn ordinary_bidi_keeps_external_space_outside_unsplit_decorations() {
        let plain = |content: &str| {
            let mut style = w3cos_std::style::Style::default();
            style.display = Display::Inline;
            w3cos_std::Component::text(content, style)
        };
        let decorated = |content: &str| {
            let mut style = w3cos_std::style::Style::default();
            style.display = Display::Inline;
            style.border_width = 3.0;
            w3cos_std::Component::row(style, vec![plain(content)])
        };
        let mut style = w3cos_std::style::Style::default();
        style.direction = w3cos_std::style::TextDirection::Rtl;
        let mut line = w3cos_std::Component::row(
            style,
            vec![decorated("inspect"), plain(" "), decorated("pause")],
        );
        reorder_explicit_bidi_inline_rows(&mut line);
        let decorated_runs = line
            .children
            .iter()
            .filter_map(|child| {
                if child.style.border_width > 0.0
                    && let ComponentKind::Text { content } = &child.kind
                {
                    Some(content.as_str())
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();
        assert_eq!(decorated_runs, ["inspect", "pause"]);
    }

    #[test]
    fn wrapped_bidi_preserves_browser_owned_visual_edge_spaces() {
        crate::stylesheet::clear_rules();
        let mut document = Document::new();
        let block = document.create_element("p");
        for (name, value) in [("width", "28em"), ("font", "16px/1 Ahem")] {
            block.style_mut(&mut document).set_property(name, value);
        }
        for (tag, content) in [
            (Some("span"), " pppp pppX ppXp \u{202e} ppXp XXpp XppX "),
            (None, " pppX XXXp pXXp "),
            (Some("span"), " XpXp ppXX XXpX pXpX \u{202c} XXpX XXXp "),
        ] {
            let text = document.create_text_node(content);
            if let Some(tag) = tag {
                let span = document.create_element(tag);
                for (name, value) in [("border", "3px solid"), ("padding", "0.4em 1em"), ("line-height", "3em")] {
                    span.style_mut(&mut document).set_property(name, value);
                }
                span.append_child(&mut document, text);
                block.append_child(&mut document, span);
            } else {
                block.append_child(&mut document, text);
            }
        }
        document.body().append_child(&mut document, block);
        let visual = descendant_text_runs(&document.to_component_tree()).iter()
            .map(|(text, _)| text.replace('\u{00a0}', " ")).collect::<String>();
        // V2850 Chromium character Ranges: source spaces survive when visual
        // reordering places them at a line edge inside an inline decoration.
        assert_eq!(visual, "pppp pppX ppXp ppXX pXpp \u{2028}pXpX pXXp pXXX Xppp XppX\u{2028} XpXp XpXX XXpp XXpX XXXp");
    }

    #[test]
    fn explicit_bidi_keeps_browser_logical_space_ownership() {
        // Chromium bidi-003 Range geometry (V2838): collapse source-adjacent
        // spaces before reordering, not the visual edges of every fragment.
        let plain = |content: &str| {
            w3cos_std::Component::text(content, w3cos_std::style::Style {
                display: Display::InlineBlock,
                ..Default::default()
            })
        };
        let decorated = |content: &str| {
            w3cos_std::Component::row(w3cos_std::style::Style {
                display: Display::Inline, border_width: 3.0,
                ..Default::default()
            }, vec![plain(content)])
        };
        let mut line = w3cos_std::Component::row(w3cos_std::style::Style {
            white_space: w3cos_std::style::WhiteSpace::NoWrap,
            ..Default::default()
        }, vec![
            decorated(" aaa bbb ccc \u{202e} lll kkk jjj "),
            plain(" iii hhh ggg "),
            decorated(" fff eee ddd \u{202c} mmm nnn ooo "),
        ]);
        reorder_explicit_bidi_inline_rows(&mut line);
        let runs = line.children.iter().filter_map(|child| {
            if let ComponentKind::Text { content } = &child.kind {
                Some((content.as_str(), child.style.border_width > 0.0))
            } else { None }
        }).collect::<Vec<_>>();
        assert_eq!(runs, vec![
            ("aaa bbb ccc ", true), (" ddd eee fff", true),
            (" ggg hhh iii", false), (" jjj kkk lll ", true),
            (" mmm nnn ooo", true),
        ]);
    }

